let accepting = true;
const inFlight = new Set();

async function handle(name) {
  if (!accepting) return console.log(`${name}: refused`);
  const job = new Promise((resolve) => setTimeout(resolve, 20)).then(() => console.log(`${name}: done`));
  inFlight.add(job);
  await job;
  inFlight.delete(job);
}

async function shutdown() {
  accepting = false;
  console.log("SIGTERM: stop accepting");
  await Promise.all(inFlight);
  console.log("closed");
}

const first = handle("order-1");
const stopping = shutdown();
await handle("order-2");
await Promise.all([first, stopping]);

