function loadConfig(env) {
  const problems = [];
  if (!/^\d+$/.test(env.PORT ?? "3000")) problems.push("PORT: must be a whole number");
  if (!env.JWT_SECRET || env.JWT_SECRET.length < 32) problems.push("JWT_SECRET: at least 32 characters");
  if (problems.length) throw new Error(`Invalid configuration:\n  ${problems.join("\n  ")}`);
  return { port: Number(env.PORT ?? "3000") };
}

try {
  loadConfig({ PORT: "eighty", JWT_SECRET: "hunter2" });
} catch (error) {
  console.log(error.message);
}

function withTimeout(work, ms) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`timed out after ${ms} ms`)), ms);
  });
  return Promise.race([work, timeout]).finally(() => clearTimeout(timer));
}

const slowQuery = new Promise((resolve) => setTimeout(() => resolve("rows"), 80));
const fastQuery = new Promise((resolve) => setTimeout(() => resolve("rows"), 5));

for (const [name, query] of [["fast", fastQuery], ["slow", slowQuery]]) {
  try {
    console.log(name, await withTimeout(query, 30));
  } catch (error) {
    console.log(name, error.message);
  }
}
